const rows = $input.all().map(i => i.json);
const seen = new Set();
const out = [];
for (const r of rows) {
  const eid = Number(r.entity_id) || 0;
  const rid = Number(r.related_id) || 0;
  const em  = String(r.entity_module  || '');
  const rm  = String(r.related_module || '');
  if (!eid || !rid || !em || !rm) continue;
  const k1 = eid + '|' + em + '|' + rid + '|' + rm;
  const k2 = rid + '|' + rm + '|' + eid + '|' + em;
  if (!seen.has(k1)) {
    seen.add(k1);
    out.push({ entity_id: eid, entity_module: em, related_id: rid, related_module: rm, synced_at: new Date().toISOString() });
  }
  if (!seen.has(k2)) {
    seen.add(k2);
    out.push({ entity_id: rid, entity_module: rm, related_id: eid, related_module: em, synced_at: new Date().toISOString() });
  }
}
// Sort by primary key tuple — same lock order across overlapping runs prevents deadlocks
out.sort((a, b) => {
  if (a.entity_id !== b.entity_id) return a.entity_id - b.entity_id;
  if (a.entity_module !== b.entity_module) return a.entity_module < b.entity_module ? -1 : 1;
  if (a.related_id !== b.related_id) return a.related_id - b.related_id;
  return a.related_module < b.related_module ? -1 : (a.related_module > b.related_module ? 1 : 0);
});
return out.map(r => ({ json: r }));
